export interface Customer {
  yearsWithMHPCO: number;
}

export interface QuoteItem {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: QuoteItem[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: {
    cause: string;
    damages: Damage[];
  };
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export type StepResult = QuoteResult | ClaimResult;

export interface ScenarioResult {
  results: StepResult[];
}

const PROCESSING_FEE = 5;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
};

const RUNE_BLOCK_SIZE = 3;
const RUNE_BLOCK_PREMIUM = 60;

const quotePremium = (items: QuoteItem[]): number => {
  const runeCount = items.filter((item) => item.type === "rune").length;
  const runesPremium =
    runeCount === RUNE_BLOCK_SIZE
      ? RUNE_BLOCK_PREMIUM
      : runeCount * BASE_PREMIUMS.rune;
  const otherItemsPremium = items
    .filter((item) => item.type !== "rune")
    .reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
  const policyBasePremium = runesPremium + otherItemsPremium;
  // 10% surcharge computed as base/10 (multiplying by 1.1 introduces float noise)
  const firstInsuranceSurcharge = policyBasePremium / 10;
  return policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE;
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const quoteStep = scenario.steps[0] as QuoteStep;
  return { results: [{ premium: quotePremium(quoteStep.items) }] };
};

