export interface Customer {
  yearsWithMHPCO: number;
}

export interface QuoteItem {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: QuoteItem[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: {
    cause: string;
    damages: Damage[];
  };
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export type StepResult = QuoteResult | ClaimResult;

export interface ScenarioResult {
  results: StepResult[];
}

const PROCESSING_FEE = 5;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const RUNE_BLOCK_SIZE = 3;
const RUNE_BLOCK_PREMIUM = 60;

const isRune = (item: QuoteItem): boolean => item.type === "rune";

// Pricing rule: a block of exactly 3 runes costs a flat block premium.
const runesPremium = (runeCount: number): number =>
  runeCount === RUNE_BLOCK_SIZE
    ? RUNE_BLOCK_PREMIUM
    : runeCount * BASE_PREMIUMS.rune;

const quotePremium = (items: QuoteItem[]): number => {
  const runeCount = items.filter(isRune).length;
  const nonRunesPremium = items
    .filter((item) => !isRune(item))
    .reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
  const policyBasePremium = runesPremium(runeCount) + nonRunesPremium;
  // 10% surcharge computed as base/10 (multiplying by 1.1 introduces float noise)
  const firstInsuranceSurcharge = policyBasePremium / 10;
  return Math.ceil(policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE);
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const quoteStep = scenario.steps[0] as QuoteStep;
  return { results: [{ premium: quotePremium(quoteStep.items) }] };
};

