export interface Customer {
  yearsWithMHPCO: number;
}

export interface QuoteItem {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: QuoteItem[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: {
    cause: string;
    damages: Damage[];
  };
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export type StepResult = QuoteResult | ClaimResult;

export interface ScenarioResult {
  results: StepResult[];
}

const PROCESSING_FEE = 5;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const COMPONENT_TYPES = ["rune", "moonstone"];
const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;

const isComponent = (item: QuoteItem): boolean =>
  COMPONENT_TYPES.includes(item.type);

const basePremiumOf = (item: QuoteItem): number => BASE_PREMIUMS[item.type];

const sumBy = <T>(values: T[], amount: (value: T) => number): number =>
  values.reduce((sum, value) => sum + amount(value), 0);

// Pricing rule: a block of exactly 3 alike components costs a flat block premium.
const componentTypePremium = (items: QuoteItem[], type: string): number => {
  const count = items.filter((item) => item.type === type).length;
  return count === COMPONENT_BLOCK_SIZE
    ? COMPONENT_BLOCK_PREMIUM
    : count * BASE_PREMIUMS[type];
};

const quotePremium = (items: QuoteItem[]): number => {
  const componentsPremium = sumBy(COMPONENT_TYPES, (type) =>
    componentTypePremium(items, type)
  );
  const mainItemsPremium = sumBy(
    items.filter((item) => !isComponent(item)),
    basePremiumOf
  );
  const policyBasePremium = componentsPremium + mainItemsPremium;
  const curseSurcharge = sumBy(
    items.filter((item) => item.cursed),
    (item) => basePremiumOf(item) / 2
  );
  // 10% surcharge computed as base/10 (multiplying by 1.1 introduces float noise)
  const firstInsuranceSurcharge = policyBasePremium / 10;
  return Math.ceil(
    policyBasePremium + curseSurcharge + firstInsuranceSurcharge + PROCESSING_FEE
  );
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const quoteStep = scenario.steps[0] as QuoteStep;
  return { results: [{ premium: quotePremium(quoteStep.items) }] };
};

