const INSURANCE_VALUES: Record<string, number> = {
  sword: 1000,
};

const DEDUCTIBLE = 100;

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const policies: QuoteItem[][] = [];
  const results = scenario.steps.map((step, index): StepResult => {
    if (step.op === "quote") {
      policies[index] = step.items;
      return {
        premium: quotePremium(step.items, scenario.customer, index > 0),
      };
    }
    const policyItems = policies[step.policy];
    const insuranceSum = sumBy(
      policyItems,
      (item) => INSURANCE_VALUES[item.type]
    );
    const cap = 2 * insuranceSum;
    const payout = sumBy(
      step.incident.damages,
      (damage) => damage.amount - DEDUCTIBLE
    );
    return { payout, remainingCap: cap - payout };
  });
  return { results };
};

