136	  const enchantmentSurcharge = itemSurcharge(
137	    items,
138	    isHighlyEnchanted,
139	    HIGH_ENCHANTMENT_SURCHARGE_PERCENT
140	  );
141	  // Policy-wide modifiers are all computed on the unmodified policy base.
142	  const firstInsuranceSurcharge = percentOf(
143	    policyBasePremium,
144	    FIRST_INSURANCE_SURCHARGE_PERCENT
145	  );
146	  const loyaltyDiscount =
147	    customer.yearsWithMHPCO >= LOYALTY_MINIMUM_YEARS
148	      ? percentOf(policyBasePremium, LOYALTY_DISCOUNT_PERCENT)
149	      : 0;
150	  const followUpContractDiscount = isFollowUpContract
151	    ? percentOf(policyBasePremium, FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT)
152	    : 0;
153	  return Math.ceil(
154	    policyBasePremium +
155	      curseSurcharge +
156	      enchantmentSurcharge +
157	      firstInsuranceSurcharge -
158	      loyaltyDiscount -
159	      followUpContractDiscount +
160	      PROCESSING_FEE
161	  );
