164	const INSURANCE_VALUES: Record<string, number> = {
165	  sword: 1000,
166	  amulet: 600,
167	  rune: 250,
168	};
169	
170	const DEDUCTIBLE = 100;
171	const CAP_MULTIPLIER = 2; // payout cap is twice the policy's insurance sum
172	
173	const insuranceSumOf = (items: QuoteItem[]): number =>
174	  sumBy(items, (item) => INSURANCE_VALUES[item.type]);
175	
176	// Claim clause: items enchanted at or above this level are only reimbursed
177	// at 50%. Distinct rule from the premium's HIGH_ENCHANTMENT_THRESHOLD (5).
178	const CLAIM_HALVING_ENCHANTMENT_THRESHOLD = 8;
179	const HALVED_REIMBURSEMENT_PERCENT = 50;
180	
181	const reimbursementFor = (
182	  policyItems: QuoteItem[],
183	  damage: Damage
184	): number => {
185	  const insuredItem = policyItems.find(
186	    (item) => item.type === damage.itemType
187	  );
188	  if (insuredItem === undefined) {
189	    throw new Error(`damaged item not covered by policy: ${damage.itemType}`);
190	  }
191	  return (insuredItem.enchantment ?? 0) >= CLAIM_HALVING_ENCHANTMENT_THRESHOLD
192	    ? percentOf(damage.amount, HALVED_REIMBURSEMENT_PERCENT)
193	    : damage.amount;
194	};
195	
196	// A policy is what a quote step creates: the insured items plus the payout
197	// cap that later claims against this policy draw down.
198	interface Policy {
199	  items: QuoteItem[];
200	  remainingCap: number;
201	}
202	
203	const openPolicy = (items: QuoteItem[]): Policy => ({
204	  items,
205	  remainingCap: CAP_MULTIPLIER * insuranceSumOf(items),
206	});
207	
208	// Claim rule: a damage entry may not report a negative amount.
209	const assertNoNegativeAmounts = (damages: Damage[]): void => {
210	  const negative = damages.find((damage) => damage.amount < 0);
211	  if (negative !== undefined) {
212	    throw new Error(`negative damage amount: ${negative.amount}`);
213	  }
214	};
215	
216	// Claim rule: per item type, an incident may not report more damaged
217	// entries than the policy insures — otherwise the whole claim is rejected.
218	// (An uninsured type fails too: its insured count is 0.)
219	const assertDamagesCovered = (policy: Policy, damages: Damage[]): void => {
220	  const damagedTypes = new Set(damages.map((damage) => damage.itemType));
221	  for (const itemType of damagedTypes) {
222	    const damagedCount = countWhere(
223	      damages,
224	      (damage) => damage.itemType === itemType
225	    );
226	    const insuredCount = countWhere(policy.items, (item) => item.type === itemType);
227	    if (damagedCount > insuredCount) {
228	      throw new Error(
229	        `more damaged ${itemType} entries than insured: ${damagedCount} > ${insuredCount}`
230	      );
231	    }
232	  }
233	};
234	
235	// Settling draws the payout down from the policy's remaining cap.
236	const settleClaim = (policy: Policy, damages: Damage[]): ClaimResult => {
237	  assertNoNegativeAmounts(damages);
238	  assertDamagesCovered(policy, damages);
239	  // Payouts round down in MHPCO's favor — mirrors the Math.ceil on premiums.
240	  const uncappedPayout = Math.floor(
241	    sumBy(damages, (damage) => reimbursementFor(policy.items, damage) - DEDUCTIBLE)
242	  );
243	  const payout = Math.min(uncappedPayout, policy.remainingCap);
244	  policy.remainingCap -= payout;
245	  return { payout, remainingCap: policy.remainingCap };
246	};
